"""赛狐开放平台客户端：token 缓存 + HMAC-SHA256 签名 + 业务接口封装。

签名规则（doc-1749562）：
  data = 按参数名排序的 "k=v" 用 & 拼接，参数为
         access_token/client_id/method/nonce/timestamp/url（body 不参与签名）
  sign = HmacSHA256(client_secret, data) 的 hex
"""
import hashlib
import hmac
import logging
import random
import time

import requests

log = logging.getLogger(__name__)


class SellfoxError(Exception):
    def __init__(self, code, msg, request_id=None):
        super().__init__(f"sellfox code={code} msg={msg} requestId={request_id}")
        self.code = code
        self.msg = msg


class SellfoxClient:
    def __init__(self, base_url, client_id, client_secret, timeout=30):
        self.base_url = base_url.rstrip("/")
        self.client_id = client_id
        self.client_secret = client_secret
        self.timeout = timeout
        self._token = None
        self._token_expire_at = 0  # epoch 秒
        # 直连、不走系统代理：赛狐校验来源IP白名单，走代理会导致出口IP漂移
        self.http = requests.Session()
        self.http.trust_env = False

    # ---- 鉴权 ----

    def _get_token(self):
        now = time.time()
        if self._token and now < self._token_expire_at - 600:  # 提前10分钟刷新
            return self._token
        r = self.http.get(
            f"{self.base_url}/api/oauth/v2/token.json",
            params={
                "client_id": self.client_id,
                "client_secret": self.client_secret,
                "grant_type": "client_credentials",
            },
            timeout=self.timeout,
        )
        r.raise_for_status()
        body = r.json()
        if body.get("code") != 0:
            raise SellfoxError(body.get("code"), body.get("msg"), body.get("requestId"))
        self._token = body["data"]["access_token"]
        self._token_expire_at = now + body["data"]["expires_in"] / 1000
        log.info("sellfox token refreshed, expires_in=%sms", body["data"]["expires_in"])
        return self._token

    def _sign(self, url_path, token, timestamp, nonce):
        params = {
            "url": url_path,
            "method": "post",
            "access_token": token,
            "client_id": self.client_id,
            "timestamp": timestamp,
            "nonce": nonce,
        }
        data = "&".join(f"{k}={v}" for k, v in sorted(params.items()))
        return hmac.new(
            self.client_secret.encode(), data.encode(), hashlib.sha256
        ).hexdigest()

    def post(self, url_path, body, retries=3):
        """调用业务接口。token 失效自动重取一次；网络错误退避重试。"""
        last_err = None
        for attempt in range(retries):
            token = self._get_token()
            ts = int(time.time() * 1000)
            nonce = random.randint(1, 99999)
            query = {
                "access_token": token,
                "client_id": self.client_id,
                "timestamp": ts,
                "nonce": nonce,
                "sign": self._sign(url_path, token, ts, nonce),
            }
            try:
                r = self.http.post(
                    f"{self.base_url}{url_path}",
                    params=query,
                    json=body,
                    headers={"Content-Type": "application/json"},
                    timeout=self.timeout,
                )
                r.raise_for_status()
                resp = r.json()
            except (requests.RequestException, ValueError) as e:
                last_err = e
                log.warning("sellfox %s 网络异常(第%d次): %s", url_path, attempt + 1, e)
                time.sleep(2**attempt)
                continue
            code = resp.get("code")
            if code == 0:
                return resp.get("data")
            # token 失效类错误：清缓存重试（具体错误码以公共报错文档 doc-1759053 为准）
            if "token" in str(resp.get("msg", "")).lower() and attempt < retries - 1:
                log.warning("sellfox token 疑似失效，重新获取: %s", resp.get("msg"))
                self._token = None
                continue
            raise SellfoxError(code, resp.get("msg"), resp.get("requestId"))
        raise SellfoxError(-1, f"重试{retries}次仍失败: {last_err}")

    # ---- 业务接口 ----

    def get_package_page(self, status, date_start, date_end, page_no=1,
                         page_size=200, shop_ids=None):
        body = {
            "pageNo": str(page_no),
            "pageSize": str(page_size),
            "packageStatus": status,
            "purchaseDateStart": date_start,
            "purchaseDateEnd": date_end,
        }
        if shop_ids:
            body["shopIdList"] = [str(s) for s in shop_ids]
        return self.post("/api/packageShip/v1/getPackagePage.json", body)

    def warehouse_list(self, page_no=1, page_size=200):
        """仓库列表。type: -1虚拟仓 0默认仓 1国内仓 2FBA仓 3海外仓"""
        return self.post(
            "/api/warehouseManage/warehouseList.json",
            {"pageNo": str(page_no), "pageSize": str(page_size)},
        )

    def query_ship_channels(self, logistics_type="1"):
        """logisticsType: 1=三方仓库物流（WMS 的渠道）"""
        return self.post(
            "/api/packageShip/queryShipChannel.json",
            {"logisticsType": [logistics_type]},
        )

    def update_package_detail(self, package_sns, warehouse_id, is_oversea,
                              provider_auth_detail_id):
        """= 网页上的"更换"仓库/渠道"""
        return self.post(
            "/api/packageShip/updatePackageDetail.json",
            {
                "packageSns": package_sns,
                "warehouseId": warehouse_id,
                "isOversea": is_oversea,
                "providerAuthDetailId": provider_auth_detail_id,
            },
        )

    def apply_track_no(self, package_sns):
        """物流下单：触发赛狐向 WMS（三方仓）推单并申请运单号"""
        return self.post(
            "/api/packageShip/applyTrackNo.json", {"packageSns": package_sns}
        )

    def weighing_shipment(self, items):
        """称重发货。items: [{originalNum, weight, weightUnit}]"""
        return self.post("/api/packageShip/weighingShipment.json", {"items": items})

    def quick_outbound(self, package_list):
        """快速出库（无需重量）。package_list: [{packageSn, carrier, trackNo,
        warehouseId, isOversea, shipmentType}]"""
        return self.post(
            "/api/packageShip/quickOutbound.json", {"packageList": package_list}
        )

"""包裹处理流水线：每轮做四步，均幂等（本地状态 + 赛狐包裹状态双确认）。

step1_discover : 拉赛狐 to_process 包裹 → 本地 NEW
step2_assign   : NEW → 选渠道 → updatePackageDetail → CHANNEL_ASSIGNED
step3_order    : CHANNEL_ASSIGNED → applyTrackNo（推 WMS）→ ORDERED
step4_close    : ORDERED → 查 WMS 出库状态 → 称重发货/快速出库 → CLOSED
"""
import datetime
import logging

from . import store as st
from .selector import NoChannelError

log = logging.getLogger(__name__)

# WMS orderStatus（Constants.java 实测确认）：0待发货 1预发货 2已发货 4平台已发货
# 注意：状态=2 但运单未生成的情况存在，闭环需同时满足"状态已发货 + 运单号存在"
WMS_SHIPPED_STATUSES = {"2", "4"}


class Pipeline:
    def __init__(self, cfg, sellfox, wms, selector, store, notifier, dry_run=False):
        self.cfg = cfg
        self.sf = sellfox
        self.wms = wms
        self.selector = selector
        self.store = store
        self.notify = notifier
        self.dry_run = dry_run

    # ---- step 1: 发现新包裹 ----

    def step1_discover(self):
        days = self.cfg["run"]["purchase_date_days"]
        end = datetime.datetime.now()
        start = end - datetime.timedelta(days=days)
        page_no, found = 1, 0
        while True:
            data = self.sf.get_package_page(
                "to_process",
                start.strftime("%Y-%m-%d %H:%M:%S"),
                end.strftime("%Y-%m-%d %H:%M:%S"),
                page_no=page_no,
                shop_ids=self.cfg["run"]["shop_whitelist"] or None,
            )
            rows = (data or {}).get("rows", [])
            for p in rows:
                order_id = (p.get("orders") or [{}])[0].get("amazonOrderId", "")
                country = (p.get("address") or {}).get("countryCode", "")
                if self.store.upsert_new(
                    p["packageSn"], p.get("shopId"), order_id, country
                ):
                    found += 1
                    # 缓存明细供选渠道用
                    self._package_cache[p["packageSn"]] = p
            if page_no >= (data or {}).get("totalPage", 1):
                break
            page_no += 1
        if found:
            log.info("step1: 新发现 %d 个待处理包裹", found)
        return found

    # ---- step 2: 选渠道 + 指派 ----

    def _match_existing_channel(self, channel_name):
        """包裹已带渠道时（channelName 形如 昇新海外仓-BLACKCAT-RM，
        取后缀匹配 config 渠道名），返回配置项或 None"""
        for ch in self.cfg["channels"]:
            if channel_name and channel_name.endswith(ch["name"]):
                return ch
        return None

    def step2_assign(self):
        keep = self.cfg["run"].get("keep_existing_channel", True)
        for row in self.store.by_state(st.NEW):
            sn = row["package_sn"]
            pkg = self._package_cache.get(sn)
            if pkg is None:
                continue  # 缓存缺失，下一轮 step1 会重新带出
            try:
                weight = self.selector.estimate_weight_g(pkg.get("items", []))
                existing = self._match_existing_channel(
                    (pkg.get("logistics") or {}).get("channelName")
                )
                if keep and existing and existing.get("enabled"):
                    # 赛狐已配好渠道且可用：不动，直接进入待下单
                    if self.dry_run:
                        log.info("[dry-run] %s 保留已有渠道 %s", sn, existing["name"])
                        continue
                    self.store.set_state(
                        sn, st.CHANNEL_ASSIGNED,
                        channel_name=existing["name"], weight_g=weight,
                    )
                    continue
                # 无渠道/渠道停用：selector 决策后指派
                if weight is None:
                    raise NoChannelError("SKU 缺重量档案")
                country = row["country"] or self.cfg["run"].get("default_country", "")
                ch = self.selector.select(country, weight)
                if self.dry_run:
                    log.info("[dry-run] %s → 渠道 %s (%dg)", sn, ch["name"], weight)
                    continue
                self.sf.update_package_detail(
                    [sn],
                    ch["warehouse_id"],  # 仓库跟渠道所属物流商走
                    self.cfg["warehouse"]["is_oversea"],
                    ch["sellfox_provider_auth_detail_id"],
                )
                self.store.set_state(
                    sn, st.CHANNEL_ASSIGNED, channel_name=ch["name"], weight_g=weight
                )
            except NoChannelError as e:
                self.store.mark_failed(sn, e)
                self.notify.warn(f"包裹 {sn} 无法选渠道: {e}，请人工处理")
            except Exception as e:
                log.exception("step2 %s 失败", sn)
                self.store.mark_failed(sn, e)
                self.notify.warn(f"包裹 {sn} 指派渠道失败: {e}")

    # ---- step 3: 物流下单（推送 WMS）----

    def step3_order(self):
        if not self.cfg["run"]["auto_apply_track_no"]:
            return
        rows = self.store.by_state(st.CHANNEL_ASSIGNED)
        if not rows:
            return
        sns = [r["package_sn"] for r in rows][:200]  # 接口单次上限200
        if self.dry_run:
            log.info("[dry-run] 物流下单: %s", sns)
            return
        result = self.sf.apply_track_no(sns) or {}
        for item in result.get("successData", []) if isinstance(result, dict) else []:
            self.store.set_state(item.get("packageSn"), st.ORDERED)
        for item in result.get("failData", []) if isinstance(result, dict) else []:
            sn, msg = item.get("packageSn"), item.get("msg")
            self.store.mark_failed(sn, msg)
            self.notify.warn(f"包裹 {sn} 物流下单失败: {msg}")
        # 返回结构若与预期不符（如整体成功无明细），保守地全部置为 ORDERED，
        # step4 之前会再用赛狐包裹状态核对
        if isinstance(result, dict) and not result.get("successData") and not result.get("failData"):
            for sn in sns:
                self.store.set_state(sn, st.ORDERED)

    # ---- step 4: WMS 出库确认 + 回传闭环 ----

    def step4_close(self):
        for row in self.store.by_state(st.ORDERED):
            sn = row["package_sn"]
            try:
                status = self.wms.query_order_status(sn) or {}
                value = str(status.get("orderStatus", ""))
                if value not in WMS_SHIPPED_STATUSES:
                    continue  # 未出库，下一轮再查
                # 双条件：状态已发货 且 运单号已生成（存在状态=2但运单未生成的情况）
                try:
                    tn = self.wms.query_tracking_number(sn) or {}
                except Exception:
                    continue  # 运单未生成，下一轮再查
                if not tn.get("trackingNumber"):
                    continue
                # 渠道一致性校验：赛狐为基准。WMS 实际承运渠道（express）
                # 与赛狐指派渠道不符时暂停闭环并告警，人工调整后自动恢复
                ch = self._match_existing_channel(row["channel_name"]) or {}
                expected = str(ch.get("expected_carrier", "")).upper()
                actual = str(tn.get("express", "")).upper()
                if (self.cfg["run"].get("hold_on_channel_mismatch", True)
                        and expected and actual and expected not in actual):
                    self.notify.warn(
                        f"包裹 {sn} 渠道不一致：赛狐指派 {row['channel_name']}"
                        f"（应走 {expected}），WMS 实际渠道 {tn.get('express')}"
                        f"（运单 {tn.get('trackingNumber')}）。已暂停回传，"
                        f"请在 WMS 调整为赛狐渠道后自动恢复"
                    )
                    continue
                if self.dry_run:
                    log.info("[dry-run] %s WMS 已出库(运单%s)，应回传赛狐",
                             sn, tn.get("trackingNumber"))
                    continue
                if self.cfg["run"]["ship_confirm_mode"] == "quick":
                    self.sf.quick_outbound([{
                        "packageSn": sn,
                        "carrier": tn.get("express", ""),
                        "trackNo": tn.get("trackingNumber", ""),
                        "warehouseId": ch.get("warehouse_id"),
                        "isOversea": 3,
                        "shipmentType": 1,
                    }])
                else:
                    self.sf.weighing_shipment([{
                        "originalNum": sn,
                        "weight": (row["weight_g"] or 0) / 1000,
                        "weightUnit": "kg",
                    }])
                self.store.set_state(sn, st.CLOSED)
                log.info("包裹 %s 发货闭环完成", sn)
            except Exception as e:
                log.exception("step4 %s 失败", sn)
                self.notify.warn(f"包裹 {sn} 发货回传失败: {e}")
                # 不置 FAILED，回传失败可下一轮重试；连续失败靠告警人工介入

    # ---- 主入口 ----

    _package_cache = {}

    def run_once(self):
        self.step1_discover()
        self.step2_assign()
        self.step3_order()
        self.step4_close()

"""WMS 对客户开放接口客户端。

鉴权（各 remote 接口统一，已实测验证 2026-07-15）：
  key       = wms_user_account_info.id
  timestamp = 秒级时间戳（服务端校验 ±300s）
  sign      = MD5(key + api_secret + timestamp) 的【大写】hex
              （服务端 Common.MD5 返回大写并区分大小写比对）
返回结构：{"success": bool, "message": str, "systemCode": int, "data": ...}
  data 可能是 JSON 字符串（服务端 JSONArray.toString），需二次解析。
"""
import hashlib
import json
import logging
import time

import requests

log = logging.getLogger(__name__)


class WmsError(Exception):
    pass


class WmsClient:
    def __init__(self, base_url, key, api_secret, timeout=30):
        self.base_url = base_url.rstrip("/")
        self.key = int(key)
        self.api_secret = api_secret
        self.timeout = timeout
        self.http = requests.Session()
        self.http.trust_env = False  # 直连，不走系统代理

    def _post(self, path, extra=None):
        ts = int(time.time())
        body = {
            "key": self.key,
            "timestamp": ts,
            "sign": hashlib.md5(
                f"{self.key}{self.api_secret}{ts}".encode()
            ).hexdigest().upper(),
        }
        body.update(extra or {})
        r = self.http.post(f"{self.base_url}{path}", json=body, timeout=self.timeout)
        r.raise_for_status()
        resp = r.json()
        if not resp.get("success"):
            raise WmsError(f"wms {path}: {resp.get('message')} (systemCode={resp.get('systemCode')})")
        data = resp.get("data")
        if isinstance(data, str):
            try:
                data = json.loads(data)
            except ValueError:
                pass  # 非 JSON 字符串则原样返回
        return data

    def query_order_status(self, platform_order_no):
        """出库单状态。platformOrderNo 与赛狐包裹的对应关系以联调为准"""
        return self._post(
            "/orderInfo/remote/queryOrderStatus.html",
            {"platformOrderNo": platform_order_no},
        )

    def query_tracking_number(self, platform_order_no):
        """返回含 express / trackingNumber"""
        return self._post(
            "/orderInfo/remote/queryTrackingNumber.html",
            {"platformOrderNo": platform_order_no},
        )

    def query_inventory(self, page=None, size=None):
        """客户库存列表：[{code(sku), num, boxNum, name}]"""
        extra = {}
        if page is not None:
            extra.update({"page": page, "size": size})
        return self._post("/customer/remoteQueryInventory.html", extra)

    def query_product_info(self, page=None, size=None):
        extra = {}
        if page is not None:
            extra.update({"page": page, "size": size})
        return self._post("/customer/remoteQueryProductInfo.html", extra)

"""渠道决策引擎：目的国 + 预估计费重 → 最优渠道（性价比/可用性）。

第一期价卡在 config.yaml 本地维护；渠道停用状态启动时用
queryShipChannel 同步一次（enabled 且赛狐侧 status=1 才可用）。
"""
import logging

log = logging.getLogger(__name__)


class NoChannelError(Exception):
    """无可用渠道——转人工"""


class ChannelSelector:
    def __init__(self, channels_cfg, sku_weights):
        self.channels = channels_cfg
        self.sku_weights = sku_weights  # {sku: 克重}

    def sync_sellfox_status(self, sellfox_channels):
        """用赛狐"查询物流渠道列表"结果刷新渠道可用状态。
        sellfox_channels: ShipChannelOpenVO 列表"""
        status_by_id = {
            c["providerAuthDetailId"]: c["status"] for c in (sellfox_channels or [])
        }
        for ch in self.channels:
            sf = status_by_id.get(ch["sellfox_provider_auth_detail_id"])
            if sf == 0 and ch.get("enabled"):
                log.warning("渠道 %s 在赛狐侧已停用，本地同步停用", ch["name"])
                ch["enabled"] = False

    def estimate_weight_g(self, items):
        """按 SKU 档案预估包裹总重（g）。缺档案的 SKU 返回 None 转人工。"""
        total = 0
        for it in items:
            sku = it.get("commoditySku") or it.get("sellerSku")
            qty = int(it.get("quantityOrdered") or 1)
            w = self.sku_weights.get(sku)
            if w is None:
                log.warning("SKU %s 无预估重量档案", sku)
                return None
            total += w * qty
        return total

    def select(self, country_code, weight_g):
        """返回最优渠道 dict；无可用渠道抛 NoChannelError。"""
        candidates = []
        for ch in self.channels:
            if not ch.get("enabled"):
                continue
            if country_code not in ch.get("countries", []):
                continue
            if weight_g and ch.get("max_weight_g") and weight_g > ch["max_weight_g"]:
                continue
            cost = ch.get("base_cost", 0) + (
                ch.get("cost_per_kg", 0) * (weight_g or 0) / 1000
            )
            candidates.append((cost, ch))
        if not candidates:
            raise NoChannelError(
                f"目的国={country_code} 重量={weight_g}g 无可用渠道"
            )
        candidates.sort(key=lambda x: x[0])
        cost, best = candidates[0]
        log.info(
            "选渠道: %s (预估运费=%.2f, 候选%d条)", best["name"], cost, len(candidates)
        )
        return best
